import { execFile } from "node:child_process";
import { promises } from "node:fs";
import path from "node:path";
import { promisify } from "node:util";
import os from "node:os";
//#region src/lib/project.server.ts
var execFileAsync = promisify(execFile);
function workspace(workspaceId = "default") {
	const safeId = workspaceId.replace(/[^a-zA-Z0-9_-]+/g, "-").slice(0, 80) || "default";
	return path.join(process.env.ROXAN_WORKSPACES_ROOT || path.join(process.env.TMPDIR || process.env.TMP || "/tmp", "roxan-workspaces"), safeId);
}
async function walk(root, current, result) {
	for (const entry of await promises.readdir(current, { withFileTypes: true })) {
		if (entry.name.startsWith(".") || entry.name === "node_modules") continue;
		const absolute = path.join(current, entry.name);
		const relative = path.relative(root, absolute);
		result.push({
			path: relative,
			type: entry.isDirectory() ? "dir" : "file"
		});
		if (entry.isDirectory()) await walk(root, absolute, result);
	}
}
async function handleProject(request) {
	let root = workspace(new URL(request.url).searchParams.get("workspaceId") || "default");
	try {
		await promises.mkdir(root, { recursive: true });
	} catch {
		const safeId = (new URL(request.url).searchParams.get("workspaceId") || "default").replace(/[^a-zA-Z0-9_-]+/g, "-").slice(0, 80) || "default";
		root = path.join(process.env.TMPDIR || process.env.TMP || "/tmp", "roxan-workspaces", safeId);
		await promises.mkdir(root, { recursive: true });
	}
	const agentPath = path.join(root, "AGENT.md");
	try {
		await promises.access(agentPath);
	} catch {
		await promises.writeFile(agentPath, "# AGENT.md\n\n## Rol\nFull-stack proje geliştir. Kullanıcı isteğini analiz et, eksik kritik bilgileri ask toolu ile sor ve çalışan sonucu doğrula.\n\n## Başlangıç\nBu dosyayı oku, workspace’i explore/dir_list ile incele, planla, uygula, test et ve sonucu özetle.\n\n## Workspace\nTüm dosyalar bu klasörde tutulur. Güvenli relative yollar kullan; workspace dışına çıkma. Mevcut dosyaları kullanıcı istemeden silme.\n\n## Kalite\nDosyayı düzenlemeden önce oku. Büyük komut çıktılarını sınırlı tut. Uygun typecheck, lint, test veya build komutunu çalıştır. Yapılmayan işi yapılmış gibi bildirme.\n", "utf8");
	}
	const url = new URL(request.url);
	if (url.searchParams.get("download") === "1") {
		const temp = await promises.mkdtemp(path.join(os.tmpdir(), "roxan-project-"));
		const filename = (url.searchParams.get("filename") || "roxan-project.zip").replace(/[^a-zA-Z0-9._-]+/g, "-").replace(/\.zip$/i, "") + ".zip";
		const zip = path.join(temp, filename);
		try {
			await execFileAsync("zip", [
				"-qr",
				zip,
				".",
				"-x",
				"node_modules/*",
				".git/*"
			], { cwd: root });
			const data = await promises.readFile(zip);
			return new Response(data, { headers: {
				"Content-Type": "application/zip",
				"Content-Disposition": `attachment; filename="${filename}"`,
				"Content-Length": String(data.byteLength),
				"Cache-Control": "no-store"
			} });
		} finally {
			await promises.rm(temp, {
				recursive: true,
				force: true
			});
		}
	}
	const entries = [];
	await walk(root, root, entries);
	return Response.json({
		root,
		entries: entries.sort((a, b) => a.path.localeCompare(b.path))
	});
}
//#endregion
export { handleProject };
